return { result: result };
}
function subtractNumbers(params: { a: number; b: number }): Record<string, any> {
return { result: params.a - params.b };
}
function greetUser(params: { name: string }): Record<string, any> {
return { greeting: `Hello, ${params.name}!` };
}
class SimpleMathToolset extends BaseToolset {
private readonly tools: BaseTool[];
constructor(prefix = "") {
super([]); // No filter
this.tools = [
new FunctionTool({
name: `${prefix}add_numbers`,
description: "Adds two numbers and stores the result in the session state.",
parameters: z.object({ a: z.number(), b: z.number() }),
execute: addNumbers,
}),
new FunctionTool({
name: `${prefix}subtract_numbers`,
description: "Subtracts the second number from the first.",
parameters: z.object({ a: z.number(), b: z.number() }),
execute: subtractNumbers,
}),
];
}
async getTools(): Promise<BaseTool[]> {
return this.tools;
}
async close(): Promise<void> {
console.log("SimpleMathToolset closed.");
}
}
async function main() {
const mathToolset = new SimpleMathToolset("calculator_");
const greetTool = new FunctionTool({
name: "greet_user",
description: "Greets the user.",
parameters: z.object({ name: z.string() }),
execute: greetUser,
});
const instruction =
`You are a calculator and a greeter.
If the user asks for a math operation, use the calculator tools.
If the user asks for a greeting, use the greet_user tool.
The result of the last math operation is stored in the 'last_math_result' state variable.`;
const calculatorAgent = new LlmAgent({
name: "calculator_agent",
instruction: instruction,
tools: [greetTool, mathToolset],
model: "gemini-2.5-flash",
});
const runner = new InMemoryRunner({ agent: calculatorAgent, appName: "toolset_app" });
await runner.sessionService.createSession({ appName: "toolset_app", userId: "user1", sessionId: "session1" });
const message: Content = createUserContent("What is 5 + 3?");
for await (const event of runner.runAsync({ userId: "user1", sessionId: "session1", newMessage: message })) {
if (isFinalResponse(event) && event.content?.parts?.length) {
const text = stringifyContent(event).trim();
if (text) {
console.log(`Response from agent: ${text}`);
}
}
}
await mathToolset.close();
}
main();
In this example:
SimpleMathToolset
implementsBaseToolset
and itsget_tools()
method returnsFunctionTool
instances foradd_numbers
andsubtract_numbers
. It also customizes their names using a prefix.- The
calculator_agent
is configured with both an individualgreet_tool
and an instance ofSimpleMathToolset
. - When
calculator_agent
is run, ADK will callmath_toolset_instance.get_tools()
. The agent's LLM will then have access togreet_user
,calculator_add_numbers
, andcalculator_subtract_numbers
to handle user requests. - The
add_numbers
tool demonstrates writing totool_context.state
, and the agent's instruction mentions reading this state. - The
close()
method is called to ensure any resources held by the toolset are released.
Toolsets offer a powerful way to organize, manage, and dynamically provide collections of tools to your ADK agents, leading to more modular, maintainable, and adaptable agentic applications.

Artifacts¶
In ADK, Artifacts represent a crucial mechanism for managing named, versioned binary data associated either with a specific user interaction session or persistently with a user across multiple sessions. They allow your agents and tools to handle data beyond simple text strings, enabling richer interactions involving files, images, audio, and other binary formats.
Note
The specific parameters or method names for the primitives may vary slightly by SDK language (e.g., save_artifact
in Python, saveArtifact
in Java). Refer to the language-specific API documentation for details.
What are Artifacts?¶
-
Definition: An Artifact is essentially a piece of binary data (like the content of a file) identified by a unique
filename
string within a specific scope (session or user). Each time you save an artifact with the same filename, a new version is created. -
Representation: Artifacts are consistently represented using the standard
google.genai.types.Part
object. The core data is typically stored within an inline data structure of thePart
(accessed viainline_data
), which itself contains:data
: The raw binary content as bytes.mime_type
: A string indicating the type of the data (e.g.,"image/png"
,"application/pdf"
). This is essential for correctly interpreting the data later.
# Example of how an artifact might be represented as a types.Part
import google.genai.types as types
# Assume 'image_bytes' contains the binary data of a PNG image
image_bytes = b'\x89PNG\r\n\x1a\n...' # Placeholder for actual image bytes
image_artifact = types.Part(
inline_data=types.Blob(
mime_type="image/png",
data=image_bytes
)
)
# You can also use the convenience constructor:
# image_artifact_alt = types.Part.from_bytes(data=image_bytes, mime_type="image/png")
print(f"Artifact MIME Type: {image_artifact.inline_data.mime_type}")
print(f"Artifact Data (first 10 bytes): {image_artifact.inline_data.data[:10]}...")
import type { Part } from '@google/genai';
import { createPartFromBase64 } from '@google/genai';
// Assume 'imageBytes' contains the binary data of a PNG image
const imageBytes = new Uint8Array([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]); // Placeholder
const imageArtifact: Part = createPartFromBase64(imageBytes.toString('base64'), "image/png");
console.log(`Artifact MIME Type: ${imageArtifact.inlineData?.mimeType}`);
// Note: Accessing raw bytes would require decoding from base64.
import (
"log"
"google.golang.org/genai"
)
// Create a byte slice with the image data.
imageBytes, err := os.ReadFile("image.png")
if err != nil {
log.Fatalf("Failed to read image file: %v", err)
}
// Create a new artifact with the image data.
imageArtifact := &genai.Part{
InlineData: &genai.Blob{
MIMEType: "image/png",
Data: imageBytes,
},
}
log.Printf("Artifact MIME Type: %s", imageArtifact.InlineData.MIMEType)
log.Printf("Artifact Data (first 8 bytes): %x...", imageArtifact.InlineData.Data[:8])
import com.google.genai.types.Part;
import java.nio.charset.StandardCharsets;
public class ArtifactExample {
public static void main(String[] args) {
// Assume 'imageBytes' contains the binary data of a PNG image
byte[] imageBytes = {(byte) 0x89, (byte) 0x50, (byte) 0x4E, (byte) 0x47, (byte) 0x0D, (byte) 0x0A, (byte) 0x1A, (byte) 0x0A, (byte) 0x01, (byte) 0x02}; // Placeholder for actual image bytes
// Create an image artifact using Part.fromBytes
Part imageArtifact = Part.fromBytes(imageBytes, "image/png");
System.out.println("Artifact MIME Type: " + imageArtifact.inlineData().get().mimeType().get());
System.out.println(
"Artifact Data (first 10 bytes): "
+ new String(imageArtifact.inlineData().get().data().get(), 0, 10, StandardCharsets.UTF_8)
+ "...");
}
}
- Persistence & Management: Artifacts are not stored directly within the agent or session state. Their storage and retrieval are managed by a dedicated Artifact Service (an implementation of
BaseArtifactService
, defined ingoogle.adk.artifacts
. ADK provides various implementations, such as:- An in-memory service for testing or temporary storage (e.g.,
InMemoryArtifactService
in Python, defined ingoogle.adk.artifacts.in_memory_artifact_service.py
). - A service for persistent storage using Google Cloud Storage (GCS) (e.g.,
GcsArtifactService
in Python, defined ingoogle.adk.artifacts.gcs_artifact_service.py
). The chosen service implementation handles versioning automatically when you save data.
- An in-memory service for testing or temporary storage (e.g.,
Why Use Artifacts?¶
While session state
is suitable for storing small pieces of configuration or conversational context (like strings, numbers, booleans, or small dictionaries/lists), Artifacts are designed for scenarios involving binary or large data:
- Handling Non-Textual Data: Easily store and retrieve images, audio clips, video snippets, PDFs, spreadsheets, or any other file format relevant to your agent's function.
- Persisting Large Data: Session state is generally not optimized for storing large amounts of data. Artifacts provide a dedicated mechanism for persisting larger blobs without cluttering the session state.
- User File Management: Provide capabilities for users to upload files (which can be saved as artifacts) and retrieve or download files generated by the agent (loaded from artifacts).
- Sharing Outputs: Enable tools or agents to generate binary outputs (like a PDF report or a generated image) that can be saved via
save_artifact
and later accessed by other parts of the application or even in subsequent sessions (if using user namespacing). - Caching Binary Data: Store the results of computationally expensive operations that produce binary data (e.g., rendering a complex chart image) as artifacts to avoid regenerating them on subsequent requests.
In essence, whenever your agent needs to work with file-like binary data that needs to be persisted, versioned, or shared, Artifacts managed by an ArtifactService
are the appropriate mechanism within ADK.
Common Use Cases¶
Artifacts provide a flexible way to handle binary data within your ADK applications.
Here are some typical scenarios where they prove valuable:
-
Generated Reports/Files:
- A tool or agent generates a report (e.g., a PDF analysis, a CSV data export, an image chart).
-
Handling User Uploads:
- A user uploads a file (e.g., an image for analysis, a document for summarization) through a front-end interface.
-
Storing Intermediate Binary Results:
- An agent performs a complex multi-step process where one step generates intermediate binary data (e.g., audio synthesis, simulation results).
-
Persistent User Data:
- Storing user-specific configuration or data that isn't a simple key-value state.
-
Caching Generated Binary Content:
- An agent frequently generates the same binary output based on certain inputs (e.g., a company logo image, a standard audio greeting).
Core Concepts¶
Understanding artifacts involves grasping a few key components: the service that manages them, the data structure used to hold them, and how they are identified and versioned.
Artifact Service (BaseArtifactService
)¶
-
Role: The central component responsible for the actual storage and retrieval logic for artifacts. It defines how and where artifacts are persisted.
-
Interface: Defined by the abstract base class
BaseArtifactService
. Any concrete implementation must provide methods for:Save Artifact
: Stores the artifact data and returns its assigned version number.Load Artifact
: Retrieves a specific version (or the latest) of an artifact.List Artifact keys
: Lists the unique filenames of artifacts within a given scope.Delete Artifact
: Removes an artifact (and potentially all its versions, depending on implementation).List versions
: Lists all available version numbers for a specific artifact filename.
-
Configuration: You provide an instance of an artifact service (e.g.,
InMemoryArtifactService
,GcsArtifactService
) when initializing theRunner
. TheRunner
then makes this service available to agents and tools via theInvocationContext
.
from google.adk.runners import Runner
from google.adk.artifacts import InMemoryArtifactService # Or GcsArtifactService
from google.adk.agents import LlmAgent # Any agent
from google.adk.sessions import InMemorySessionService
# Example: Configuring the Runner with an Artifact Service
my_agent = LlmAgent(name="artifact_user_agent", model="gemini-2.0-flash")
artifact_service = InMemoryArtifactService() # Choose an implementation
session_service = InMemorySessionService()
runner = Runner(
agent=my_agent,
app_name="my_artifact_app",
session_service=session_service,
artifact_service=artifact_service # Provide the service instance here
)
# Now, contexts within runs managed by this runner can use artifact methods
