Accessing Methods¶
The artifact interaction methods are available directly on instances of CallbackContext
(passed to agent and model callbacks) and ToolContext
(passed to tool callbacks). Remember that ToolContext
inherits from CallbackContext
.
Saving Artifacts¶
-
Code Example:
import google.genai.types as types from google.adk.agents.callback_context import CallbackContext # Or ToolContext async def save_generated_report_py(context: CallbackContext, report_bytes: bytes): """Saves generated PDF report bytes as an artifact.""" report_artifact = types.Part.from_bytes( data=report_bytes, mime_type="application/pdf" ) filename = "generated_report.pdf" try: version = await context.save_artifact(filename=filename, artifact=report_artifact) print(f"Successfully saved Python artifact '{filename}' as version {version}.") # The event generated after this callback will contain: # event.actions.artifact_delta == {"generated_report.pdf": version} except ValueError as e: print(f"Error saving Python artifact: {e}. Is ArtifactService configured in Runner?") except Exception as e: # Handle potential storage errors (e.g., GCS permissions) print(f"An unexpected error occurred during Python artifact save: {e}") # --- Example Usage Concept (Python) --- # async def main_py(): # callback_context: CallbackContext = ... # obtain context # report_data = b'...' # Assume this holds the PDF bytes # await save_generated_report_py(callback_context, report_data)
import type { Part } from '@google/genai'; import { createPartFromBase64 } from '@google/genai'; import { CallbackContext } from '@google/adk'; async function saveGeneratedReport(context: CallbackContext, reportBytes: Uint8Array): Promise<void> { /**Saves generated PDF report bytes as an artifact.*/ const reportArtifact: Part = createPartFromBase64(reportBytes.toString('base64'), "application/pdf"); const filename = "generated_report.pdf"; try { const version = await context.saveArtifact(filename, reportArtifact); console.log(`Successfully saved TypeScript artifact '${filename}' as version ${version}.`); } catch (e: any) { console.error(`Error saving TypeScript artifact: ${e.message}. Is ArtifactService configured in Runner?`); } }
import ( "log" "google.golang.org/adk/agent" "google.golang.org/adk/llm" "google.golang.org/genai" ) // saveReportCallback is a BeforeModel callback that saves a report from session state. func saveReportCallback(ctx agent.CallbackContext, req *model.LLMRequest) (*model.LLMResponse, error) { // Get the report data from the session state. reportData, err := ctx.State().Get("report_bytes") if err != nil { log.Printf("No report data found in session state: %v", err) return nil, nil // No report to save, continue normally. } // Check if the report data is in the expected format. reportBytes, ok := reportData.([]byte) if !ok { log.Printf("Report data in session state was not in the expected byte format.") return nil, nil } // Create a new artifact with the report data. reportArtifact := &genai.Part{ InlineData: &genai.Blob{ MIMEType: "application/pdf", Data: reportBytes, }, } // Set the filename for the artifact. filename := "generated_report.pdf" // Save the artifact to the artifact service. _, err = ctx.Artifacts().Save(ctx, filename, reportArtifact) if err != nil { log.Printf("An unexpected error occurred during Go artifact save: %v", err) // Depending on requirements, you might want to return an error to the user. return nil, nil } log.Printf("Successfully saved Go artifact '%s'.", filename) // Return nil to continue to the next callback or the model. return nil, nil }
