import google.genai.types as types from google.adk.agents.callback_context import CallbackContext # Or ToolContext async def process_latest_report_py(context: CallbackContext): """Loads the latest report artifact and processes its data.""" filename = "generated_report.pdf" try: # Load the latest version report_artifact = await context.load_artifact(filename=filename) if report_artifact and report_artifact.inline_data: print(f"Successfully loaded latest Python artifact '{filename}'.") print(f"MIME Type: {report_artifact.inline_data.mime_type}") # Process the report_artifact.inline_data.data (bytes) pdf_bytes = report_artifact.inline_data.data print(f"Report size: {len(pdf_bytes)} bytes.") # ... further processing ... else: print(f"Python artifact '{filename}' not found.") # Example: Load a specific version (if version 0 exists) # specific_version_artifact = await context.load_artifact(filename=filename, version=0) # if specific_version_artifact: # print(f"Loaded version 0 of '{filename}'.") except ValueError as e: print(f"Error loading Python artifact: {e}. Is ArtifactService configured?") except Exception as e: # Handle potential storage errors print(f"An unexpected error occurred during Python artifact load: {e}") # --- Example Usage Concept (Python) --- # async def main_py(): # callback_context: CallbackContext = ... # obtain context # await process_latest_report_py(callback_context)
import { CallbackContext } from '@google/adk'; async function processLatestReport(context: CallbackContext): Promise<void> { /**Loads the latest report artifact and processes its data.*/ const filename = "generated_report.pdf"; try { // Load the latest version const reportArtifact = await context.loadArtifact(filename); if (reportArtifact?.inlineData) { console.log(`Successfully loaded latest TypeScript artifact '${filename}'.`); console.log(`MIME Type: ${reportArtifact.inlineData.mimeType}`); // Process the reportArtifact.inlineData.data (base64 string) const pdfData = Buffer.from(reportArtifact.inlineData.data, 'base64'); console.log(`Report size: ${pdfData.length} bytes.`); // ... further processing ... } else { console.log(`TypeScript artifact '${filename}' not found.`); } } catch (e: any) { console.error(`Error loading TypeScript artifact: ${e.message}. Is ArtifactService configured?`); } }
import ( "log" "google.golang.org/adk/agent" "google.golang.org/adk/llm" ) // loadArtifactsCallback is a BeforeModel callback that loads a specific artifact // and adds its content to the LLM request. func loadArtifactsCallback(ctx agent.CallbackContext, req *model.LLMRequest) (*model.LLMResponse, error) { log.Println("[Callback] loadArtifactsCallback triggered.") // In a real app, you would parse the user's request to find a filename. // For this example, we'll hardcode a filename to demonstrate. const filenameToLoad = "generated_report.pdf" // Load the artifact from the artifact service. loadedPartResponse, err := ctx.Artifacts().Load(ctx, filenameToLoad) if err != nil { log.Printf("Callback could not load artifact '%s': %v", filenameToLoad, err) return nil, nil // File not found or error, continue to model. } loadedPart := loadedPartResponse.Part log.Printf("Callback successfully loaded artifact '%s'.", filenameToLoad) // Ensure there's at least one content in the request to append to. if len(req.Contents) == 0 { req.Contents = []*genai.Content{{Parts: []*genai.Part{ genai.NewPartFromText("SYSTEM: The following file is provided for context:\n"), }}} } // Add the loaded artifact to the request for the model. lastContent := req.Contents[len(req.Contents)-1] lastContent.Parts = append(lastContent.Parts, loadedPart) log.Printf("Added artifact '%s' to LLM request.", filenameToLoad) // Return nil to continue to the next callback or the model. return nil, nil // Continue to next callback or LLM call }
import com.google.adk.artifacts.BaseArtifactService; import com.google.genai.types.Part; import io.reactivex.rxjava3.core.MaybeObserver; import io.reactivex.rxjava3.disposables.Disposable; import java.util.Optional; public class MyArtifactLoaderService { private final BaseArtifactService artifactService; private final String appName; public MyArtifactLoaderService(BaseArtifactService artifactService, String appName) { this.artifactService = artifactService; this.appName = appName; } public void processLatestReportJava(String userId, String sessionId, String filename) { // Load the latest version by passing Optional.empty() for the version artifactService .loadArtifact(appName, userId, sessionId, filename, Optional.empty()) .subscribe( new MaybeObserver<Part>() { @Override public void onSubscribe(Disposable d) { // Optional: handle subscription } @Override public void onSuccess(Part reportArtifact) { System.out.println( "Successfully loaded latest Java artifact '" + filename + "'."); reportArtifact .inlineData() .ifPresent( blob -> { System.out.println( "MIME Type: " + blob.mimeType().orElse("N/A")); byte[] pdfBytes = blob.data().orElse(new byte[0]); System.out.println("Report size: " + pdfBytes.length + " bytes."); // ... further processing of pdfBytes ... }); } @Override public void onError(Throwable e) { // Handle potential storage errors or other exceptions System.err.println( "An error occurred during Java artifact load for '" + filename + "': " + e.getMessage()); } @Override public void onComplete() { // Called if the artifact (latest version) is not found System.out.println("Java artifact '" + filename + "' not found."); } }); // Example: Load a specific version (e.g., version 0) /* artifactService.loadArtifact(appName, userId, sessionId, filename, Optional.of(0)) .subscribe(part -> { System.out.println("Loaded version 0 of Java artifact '" + filename + "'."); }, throwable -> { System.err.println("Error loading version 0 of '" + filename + "': " + throwable.getMessage()); }, () -> { System.out.println("Version 0 of Java artifact '" + filename + "' not found."); }); */ } // --- Example Usage Concept (Java) --- public static void main(String[] args) { // BaseArtifactService service = new InMemoryArtifactService(); // Or GcsArtifactService // MyArtifactLoaderService loader = new MyArtifactLoaderService(service, "myJavaApp"); // loader.processLatestReportJava("user123", "sessionABC", "java_report.pdf"); // Due to async nature, in a real app, ensure program waits or handles completion. } }
