Code Example:
from google.adk.tools.tool_context import ToolContext def list_user_files_py(tool_context: ToolContext) -> str: """Tool to list available artifacts for the user.""" try: available_files = await tool_context.list_artifacts() if not available_files: return "You have no saved artifacts." else: # Format the list for the user/LLM file_list_str = "\n".join([f"- {fname}" for fname in available_files]) return f"Here are your available Python artifacts:\n{file_list_str}" except ValueError as e: print(f"Error listing Python artifacts: {e}. Is ArtifactService configured?") return "Error: Could not list Python artifacts." except Exception as e: print(f"An unexpected error occurred during Python artifact list: {e}") return "Error: An unexpected error occurred while listing Python artifacts." # This function would typically be wrapped in a FunctionTool # from google.adk.tools import FunctionTool # list_files_tool = FunctionTool(func=list_user_files_py)
import { ToolContext } from '@google/adk'; async function listUserFiles(toolContext: ToolContext): Promise<string> { /**Tool to list available artifacts for the user.*/ try { const availableFiles = await toolContext.listArtifacts(); if (!availableFiles || availableFiles.length === 0) { return "You have no saved artifacts."; } else { // Format the list for the user/LLM const fileListStr = availableFiles.map(fname => `- ${fname}`).join("\n"); return `Here are your available TypeScript artifacts:\n${fileListStr}`; } } catch (e: any) { console.error(`Error listing TypeScript artifacts: ${e.message}. Is ArtifactService configured?`); return "Error: Could not list TypeScript artifacts."; } }
import ( "fmt" "log" "strings" "google.golang.org/adk/agent" "google.golang.org/adk/llm" "google.golang.org/genai" ) // listUserFilesCallback is a BeforeModel callback that lists available artifacts // and adds the list as context to the LLM request. func listUserFilesCallback(ctx agent.CallbackContext, req *model.LLMRequest) (*model.LLMResponse, error) { log.Println("[Callback] listUserFilesCallback triggered.") // List the available artifacts from the artifact service. listResponse, err := ctx.Artifacts().List(ctx) if err != nil { log.Printf("An unexpected error occurred during Go artifact list: %v", err) return nil, nil // Continue, but log the error. } availableFiles := listResponse.FileNames log.Printf("Found %d available files.", len(availableFiles)) // If there are available files, add them to the LLM request. if len(availableFiles) > 0 { var fileListStr strings.Builder fileListStr.WriteString("SYSTEM: The following files are available:\n") for _, fname := range availableFiles { fileListStr.WriteString(fmt.Sprintf("- %s\n", fname)) } // Prepend this information to the user's request for the model. if len(req.Contents) > 0 { lastContent := req.Contents[len(req.Contents)-1] if len(lastContent.Parts) > 0 { fileListStr.WriteString("\n") // Add a newline for separation. lastContent.Parts[0] = genai.NewPartFromText(fileListStr.String() + lastContent.Parts[0].Text) log.Println("Added file list to LLM request context.") } } log.Printf("Available files:\n%s", fileListStr.String()) } else { log.Println("No available files found to list.") } // Return nil to continue to the next callback or the model. return nil, nil // Continue to next callback or LLM call }
import com.google.adk.artifacts.BaseArtifactService; import com.google.adk.artifacts.ListArtifactsResponse; import com.google.common.collect.ImmutableList; import io.reactivex.rxjava3.core.SingleObserver; import io.reactivex.rxjava3.disposables.Disposable; public class MyArtifactListerService { private final BaseArtifactService artifactService; private final String appName; public MyArtifactListerService(BaseArtifactService artifactService, String appName) { this.artifactService = artifactService; this.appName = appName; } // Example method that might be called by a tool or agent logic public void listUserFilesJava(String userId, String sessionId) { artifactService .listArtifactKeys(appName, userId, sessionId) .subscribe( new SingleObserver<ListArtifactsResponse>() { @Override public void onSubscribe(Disposable d) { // Optional: handle subscription } @Override public void onSuccess(ListArtifactsResponse response) { ImmutableList<String> availableFiles = response.filenames(); if (availableFiles.isEmpty()) { System.out.println( "User " + userId + " in session " + sessionId + " has no saved Java artifacts."); } else { StringBuilder fileListStr = new StringBuilder( "Here are the available Java artifacts for user " + userId + " in session " + sessionId + ":\n"); for (String fname : availableFiles) { fileListStr.append("- ").append(fname).append("\n"); } System.out.println(fileListStr.toString()); } } @Override public void onError(Throwable e) { System.err.println( "Error listing Java artifacts for user " + userId + " in session " + sessionId + ": " + e.getMessage()); // In a real application, you might return an error message to the user/LLM } }); } // --- Example Usage Concept (Java) --- public static void main(String[] args) { // BaseArtifactService service = new InMemoryArtifactService(); // Or GcsArtifactService // MyArtifactListerService lister = new MyArtifactListerService(service, "myJavaApp"); // lister.listUserFilesJava("user123", "sessionABC"); // Due to async nature, in a real app, ensure program waits or handles completion. } }
These methods for saving, loading, and listing provide a convenient and consistent way to manage binary data persistence within ADK, whether using Python's context objects or directly interacting with the BaseArtifactService
in Java, regardless of the chosen backend storage implementation.
Available Implementations¶
ADK provides concrete implementations of the BaseArtifactService
interface, offering different storage backends suitable for various development stages and deployment needs. These implementations handle the details of storing, versioning, and retrieving artifact data based on the app_name
, user_id
, session_id
, and filename
(including the user:
namespace prefix).
InMemoryArtifactService¶
- Storage Mechanism:
- Python: Uses a Python dictionary (
self.artifacts
) held in the application's memory. The dictionary keys represent the artifact path, and the values are lists oftypes.Part
, where each list element is a version. - Java: Uses nested
HashMap
instances (private final Map<String, Map<String, Map<String, Map<String, List<Part>>>>> artifacts;
) held in memory. The keys at each level areappName
,userId
,sessionId
, andfilename
respectively. The innermostList<Part>
stores the versions of the artifact, where the list index corresponds to the version number.
- Python: Uses a Python dictionary (
- Key Features:
- Simplicity: Requires no external setup or dependencies beyond the core ADK library.
- Speed: Operations are typically very fast as they involve in-memory map/dictionary lookups and list manipulations.
- Ephemeral: All stored artifacts are lost when the application process terminates. Data does not persist between application restarts.
- Use Cases:
- Ideal for local development and testing where persistence is not required.
- Suitable for short-lived demonstrations or scenarios where artifact data is purely temporary within a single run of the application.
-
Instantiation:
import { InMemoryArtifactService } from '@google/adk'; // Simply instantiate the class const inMemoryService = new InMemoryArtifactService(); // This instance would then be provided to your Runner. // const runner = new InMemoryRunner({ // /* other services */, // artifactService: inMemoryService // });
import ( "google.golang.org/adk/artifactservice" ) // Simply instantiate the service artifactService := artifact.InMemoryService() log.Printf("InMemoryArtifactService (Go) instantiated: %T", artifactService) // Use the service in your runner // r, _ := runner.New(runner.Config{ // Agent: agent, // AppName: "my_app", // SessionService: sessionService, // ArtifactService: artifactService, // })
import com.google.adk.artifacts.BaseArtifactService; import com.google.adk.artifacts.InMemoryArtifactService; public class InMemoryServiceSetup { public static void main(String[] args) { // Simply instantiate the class BaseArtifactService inMemoryServiceJava = new InMemoryArtifactService(); System.out.println("InMemoryArtifactService (Java) instantiated: " + inMemoryServiceJava.getClass().getName()); // This instance would then be provided to your Runner. // Runner runner = new Runner( // /* other services */, // inMemoryServiceJava // ); } }
GcsArtifactService¶
- Storage Mechanism: Leverages Google Cloud Storage (GCS) for persistent artifact storage. Each version of an artifact is stored as a separate object (blob) within a specified GCS bucket.
- Object Naming Convention: It constructs GCS object names (blob names) using a hierarchical path structure.
- Key Features:
- Persistence: Artifacts stored in GCS persist across application restarts and deployments.
- Scalability: Leverages the scalability and durability of Google Cloud Storage.
- Versioning: Explicitly stores each version as a distinct GCS object. The
saveArtifact
method inGcsArtifactService
. - Permissions Required: The application environment needs appropriate credentials (e.g., Application Default Credentials) and IAM permissions to read from and write to the specified GCS bucket.
- Use Cases:
- Production environments requiring persistent artifact storage.
- Scenarios where artifacts need to be shared across different application instances or services (by accessing the same GCS bucket).
- Applications needing long-term storage and retrieval of user or session data.
-
Instantiation:
from google.adk.artifacts import GcsArtifactService # Specify the GCS bucket name gcs_bucket_name_py = "your-gcs-bucket-for-adk-artifacts" # Replace with your bucket name try: gcs_service_py = GcsArtifactService(bucket_name=gcs_bucket_name_py) print(f"Python GcsArtifactService initialized for bucket: {gcs_bucket_name_py}") # Ensure your environment has credentials to access this bucket. # e.g., via Application Default Credentials (ADC) # Then pass it to the Runner # runner = Runner(..., artifact_service=gcs_service_py) except Exception as e: # Catch potential errors during GCS client initialization (e.g., auth issues) print(f"Error initializing Python GcsArtifactService: {e}") # Handle the error appropriately - maybe fall back to InMemory or raise
import com.google.adk.artifacts.BaseArtifactService; import com.google.adk.artifacts.GcsArtifactService; import com.google.cloud.storage.Storage; import com.google.cloud.storage.StorageOptions; public class GcsServiceSetup { public static void main(String[] args) { // Specify the GCS bucket name String gcsBucketNameJava = "your-gcs-bucket-for-adk-artifacts"; // Replace with your bucket name try { // Initialize the GCS Storage client. // This will use Application Default Credentials by default. // Ensure the environment is configured correctly (e.g., GOOGLE_APPLICATION_CREDENTIALS). Storage storageClient = StorageOptions.getDefaultInstance().getService(); // Instantiate the GcsArtifactService BaseArtifactService gcsServiceJava = new GcsArtifactService(gcsBucketNameJava, storageClient); System.out.println( "Java GcsArtifactService initialized for bucket: " + gcsBucketNameJava); // This instance would then be provided to your Runner. // Runner runner = new Runner( // /* other services */, // gcsServiceJava // ); } catch (Exception e) { // Catch potential errors during GCS client initialization (e.g., auth, permissions) System.err.println("Error initializing Java GcsArtifactService: " + e.getMessage()); e.printStackTrace(); // Handle the error appropriately } } }
Choosing the appropriate ArtifactService
implementation depends on your application's requirements for data persistence, scalability, and operational environment.
Best Practices¶
To use artifacts effectively and maintainably:
- Choose the Right Service: Use
InMemoryArtifactService
for rapid prototyping, testing, and scenarios where persistence isn't needed. UseGcsArtifactService
(or implement your ownBaseArtifactService
for other backends) for production environments requiring data persistence and scalability. - Meaningful Filenames: Use clear, descriptive filenames. Including relevant extensions (
.pdf
,.png
,.wav
) helps humans understand the content, even though themime_type
dictates programmatic handling. Establish conventions for temporary vs. persistent artifact names. - Specify Correct MIME Types: Always provide an accurate
mime_type
when creating thetypes.Part
forsave_artifact
. This is critical for applications or tools that laterload_artifact
to interpret thebytes
data correctly. Use standard IANA MIME types where possible. - Understand Versioning: Remember that
load_artifact()
without a specificversion
argument retrieves the latest version. If your logic depends on a specific historical version of an artifact, be sure to provide the integer version number when loading. - Use Namespacing (
user:
) Deliberately: Only use the"user:"
prefix for filenames when the data truly belongs to the user and should be accessible across all their sessions. For data specific to a single conversation or session, use regular filenames without the prefix. - Error Handling:
- Always check if an
artifact_service
is actually configured before calling context methods (save_artifact
,load_artifact
,list_artifacts
) – they will raise aValueError
if the service isNone
. - Check the return value of
load_artifact
, as it will beNone
if the artifact or version doesn't exist. Don't assume it always returns aPart
. - Be prepared to handle exceptions from the underlying storage service, especially with
GcsArtifactService
(e.g.,google.api_core.exceptions.Forbidden
for permission issues,NotFound
if the bucket doesn't exist, network errors).
- Always check if an
- Size Considerations: Artifacts are suitable for typical file sizes, but be mindful of potential costs and performance impacts with extremely large files, especially with cloud storage.
InMemoryArtifactService
can consume significant memory if storing many large artifacts. Evaluate if very large data might be better handled through direct GCS links or other specialized storage solutions rather than passing entire byte arrays in-memory. - Cleanup Strategy: For persistent storage like
GcsArtifactService
, artifacts remain until explicitly deleted. If artifacts represent temporary data or have a limited lifespan, implement a strategy for cleanup. This might involve:- Using GCS lifecycle policies on the bucket.
- Building specific tools or administrative functions that utilize the
artifact_service.delete_artifact
method (note: delete is not exposed via context objects for safety). - Carefully managing filenames to allow pattern-based deletion if needed.

Events¶
Events are the fundamental units of information flow within the Agent Development Kit (ADK). They represent every significant occurrence during an agent's interaction lifecycle, from initial user input to the final response and all the steps in between. Understanding events is crucial because they are the primary way components communicate, state is managed, and control flow is directed.
What Events Are and Why They Matter¶
An Event
in ADK is an immutable record representing a specific point in the agent's execution. It captures user messages, agent replies, requests to use tools (function calls), tool results, state changes, control signals, and errors.
Technically, it's an instance of the google.adk.events.Event
class, which builds upon the basic LlmResponse
structure by adding essential ADK-specific metadata and an actions
payload.
# Conceptual Structure of an Event (Python)
# from google.adk.events import Event, EventActions
# from google.genai import types
# class Event(LlmResponse): # Simplified view
# # --- LlmResponse fields ---
# content: Optional[types.Content]
# partial: Optional[bool]
# # ... other response fields ...
# # --- ADK specific additions ---
# author: str # 'user' or agent name
# invocation_id: str # ID for the whole interaction run
# id: str # Unique ID for this specific event
# timestamp: float # Creation time
# actions: EventActions # Important for side-effects & control
# branch: Optional[str] # Hierarchy path
# # ...
In Go, this is a struct of type google.golang.org/adk/session.Event
.
// Conceptual Structure of an Event (Go - See session/session.go)
// Simplified view based on the session.Event struct
type Event struct {
// --- Fields from embedded model.LLMResponse ---
model.LLMResponse
// --- ADK specific additions ---
Author string // 'user' or agent name
InvocationID string // ID for the whole interaction run
ID string // Unique ID for this specific event
Timestamp time.Time // Creation time
Actions EventActions // Important for side-effects & control
Branch string // Hierarchy path
// ... other fields
}
// model.LLMResponse contains the Content field
type LLMResponse struct {
Content *genai.Content
// ... other fields
}
In Java, this is an instance of the com.google.adk.events.Event
class. It also builds upon a basic response structure by adding essential ADK-specific metadata and an actions
payload.
